Then
\begin{align*} \det(D) &= 2 \begin{vmatrix} \frac{1}{2} & \sqrt{2} \\ \frac{1}{2} & 1 \end{vmatrix} - 1 \begin{vmatrix} \frac{1}{2} & \sqrt{2} \\ 1 & 1 \end{vmatrix} + 1 \begin{vmatrix} \frac{1}{2} & \frac{1}{2} \\ 1 & \frac{1}{2} \end{vmatrix} \\ &= 2 \left( \frac{1}{2} - \sqrt{2} \frac{1}{2} \right) - 1 \left( \frac{1}{2} - \sqrt{2} \right) + 1 \left( \frac{1}{4} - \frac{1}{4} \right) \\ &= 2 \left( \frac{1 - \sqrt{2}}{2} \right) - \left( \frac{1}{2} - \sqrt{2} \right) + 0 \\ &= 1 - \sqrt{2} - \frac{1}{2} + \sqrt{2} \\ &= \frac{1}{2} \end{align*}
